<?php declare(strict_types=1); ?>
<div class="card mb-3"><div class="card-body"><form method="get" class="row g-2"><div class="col-md-3"><input class="form-control" name="modulo" value="<?= e($filters['modulo'] ?? '') ?>" placeholder="Módulo"></div><div class="col-md-3"><input class="form-control" name="accion" value="<?= e($filters['accion'] ?? '') ?>" placeholder="Acción"></div><div class="col-md-2"><input class="form-control" type="date" name="desde" value="<?= e($filters['desde'] ?? '') ?>"></div><div class="col-md-2"><input class="form-control" type="date" name="hasta" value="<?= e($filters['hasta'] ?? '') ?>"></div><div class="col-md-2"><button class="btn btn-primary w-100">Filtrar</button></div></form></div></div>
<div class="card"><div class="card-header"><h2 class="card-title">Eventos (<?= (int) $total ?>)</h2></div><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>Fecha</th><th>Firma</th><th>Usuario</th><th>Módulo</th><th>Acción</th><th>Entidad</th></tr></thead><tbody><?php foreach ($events as $event): ?><tr><td><?= e($event['created_at']) ?></td><td><?= e($event['firma_nombre'] ?? 'Global') ?></td><td><?= e($event['usuario_nombre'] ?? 'Sistema') ?></td><td><?= e($event['modulo']) ?></td><td><code><?= e($event['accion']) ?></code></td><td><?= e(($event['entidad_tipo'] ?? '') . ' #' . ($event['entidad_id'] ?? '')) ?></td></tr><?php endforeach; ?><?php if($events===[]): ?><tr><td colspan="6" class="text-center text-secondary py-4">No hay eventos para los filtros.</td></tr><?php endif; ?></tbody></table></div></div>

